create or replace function catalog._product_soft_delete_result_row(
  p_tenant_id uuid,
  p_product_id uuid,
  p_reason text,
  p_issues jsonb,
  p_history_id uuid
)
returns table (
  product_id uuid,
  is_soft_deleted boolean,
  business_status text,
  readiness_status text,
  readiness_blockers jsonb,
  version integer,
  reason text,
  issues jsonb,
  history_entry jsonb
)
language sql
stable
security definer
set search_path = catalog, pg_temp
as $$
  select
    p.id as product_id,
    (p.business_status = 'soft_deleted'::catalog.product_business_status) as is_soft_deleted,
    p.business_status::text as business_status,
    r.status::text as readiness_status,
    coalesce(r.blockers, '[]'::jsonb) as readiness_blockers,
    p.version,
    nullif(btrim(coalesce(p_reason, '')), '') as reason,
    coalesce(p_issues, '[]'::jsonb) as issues,
    case
      when h.id is null then null
      else jsonb_build_object(
        'id', h.id,
        'occurred_at', h.created_at,
        'actor_display_name', left(h.actor_id::text, 8),
        'change_type', h.action,
        'summary', case
          when p.business_status = 'soft_deleted'::catalog.product_business_status then 'Xóa mềm sản phẩm'
          else 'Khôi phục sản phẩm'
        end,
        'value_before', h.payload ->> 'value_before',
        'value_after', h.payload ->> 'value_after'
      )
    end as history_entry
  from catalog.products p
  left join catalog.product_readiness r
    on r.product_id = p.id
   and r.tenant_id = p.tenant_id
  left join catalog.product_change_history h
    on h.id = p_history_id
   and h.product_id = p.id
   and h.tenant_id = p.tenant_id
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id;
$$;

create or replace function catalog.check_product_deletion_eligibility(
  p_tenant_id uuid,
  p_product_id uuid
)
returns table (
  product_id uuid,
  can_delete boolean,
  issues jsonb,
  suggested_action_id text
)
language plpgsql
stable
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_product catalog.products%rowtype;
  v_issues jsonb := '[]'::jsonb;
  v_has_blocker boolean := false;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.delete') then
    raise exception 'permission denied: catalog.product.delete';
  end if;

  select *
  into v_product
  from catalog.products p
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id;

  if not found then
    raise exception 'product not found';
  end if;

  if v_product.business_status = 'soft_deleted'::catalog.product_business_status then
    return query
    select
      p_product_id,
      false,
      jsonb_build_array(jsonb_build_object(
        'code', 'already_soft_deleted',
        'message', 'Sản phẩm đã được xóa mềm.',
        'severity', 'blocker'
      )),
      null::text;
    return;
  end if;

  v_issues := catalog._product_deletion_issues(p_tenant_id, p_product_id);
  v_has_blocker := catalog._product_deletion_has_blocker(v_issues);

  return query
  select
    p_product_id,
    not v_has_blocker,
    v_issues,
    case
      when jsonb_array_length(v_issues) > 0 then 'deactivate_product'
      else null
    end;
end;
$$;

create or replace function catalog.delete_product(
  p_tenant_id uuid,
  p_product_id uuid,
  p_actor_id uuid default auth.uid(),
  p_reason text default null,
  p_expected_version integer default null,
  p_confirm_acknowledge_warnings boolean default false
)
returns table (
  product_id uuid,
  is_soft_deleted boolean,
  business_status text,
  readiness_status text,
  readiness_blockers jsonb,
  version integer,
  reason text,
  issues jsonb,
  history_entry jsonb
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
#variable_conflict use_column
declare
  v_product catalog.products%rowtype;
  v_issues jsonb := '[]'::jsonb;
  v_has_blocker boolean := false;
  v_history_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.delete') then
    raise exception 'permission denied: catalog.product.delete';
  end if;

  select *
  into v_product
  from catalog.products p
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id
  for update;

  if not found then
    raise exception 'product not found';
  end if;

  if v_product.business_status = 'soft_deleted'::catalog.product_business_status then
    raise exception 'validation_exception: Product is already soft-deleted.';
  end if;

  if p_expected_version is not null and p_expected_version <> v_product.version then
    raise exception 'stale_product_version: expected=% current=%',
      p_expected_version,
      v_product.version;
  end if;

  v_issues := catalog._product_deletion_issues(p_tenant_id, p_product_id);
  v_has_blocker := catalog._product_deletion_has_blocker(v_issues);

  if v_has_blocker then
    raise exception 'product_delete_blocked: %', v_issues::text;
  end if;

  if jsonb_array_length(v_issues) > 0 and not coalesce(p_confirm_acknowledge_warnings, false) then
    raise exception 'product_delete_blocked: warnings require acknowledgment';
  end if;

  update catalog.products
  set business_status = 'soft_deleted'::catalog.product_business_status,
      deleted_at = now(),
      updated_at = now(),
      updated_by = p_actor_id,
      version = catalog.products.version + 1
  where tenant_id = p_tenant_id
    and id = p_product_id;

  perform * from catalog._refresh_product_readiness(p_tenant_id, p_product_id);

  insert into catalog.product_change_history (
    tenant_id,
    product_id,
    action,
    payload,
    actor_id
  )
  values (
    p_tenant_id,
    p_product_id,
    'product_soft_deleted',
    jsonb_build_object(
      'value_before', v_product.business_status::text,
      'value_after', 'soft_deleted',
      'reason', nullif(btrim(coalesce(p_reason, '')), ''),
      'issues', v_issues
    ),
    p_actor_id
  )
  returning id into v_history_id;

  perform catalog.enqueue_outbox_message(
    p_tenant_id,
    'catalog.product.deleted',
    jsonb_build_object(
      'tenant_id', p_tenant_id,
      'product_id', p_product_id,
      'business_status', v_product.business_status::text,
      'reason', nullif(btrim(coalesce(p_reason, '')), '')
    )
  );

  return query
  select *
  from catalog._product_soft_delete_result_row(
    p_tenant_id,
    p_product_id,
    p_reason,
    v_issues,
    v_history_id
  );
end;
$$;

create or replace function catalog.restore_product(
  p_tenant_id uuid,
  p_product_id uuid,
  p_actor_id uuid default auth.uid(),
  p_reason text default null,
  p_expected_version integer default null
)
returns table (
  product_id uuid,
  is_soft_deleted boolean,
  business_status text,
  readiness_status text,
  readiness_blockers jsonb,
  version integer,
  reason text,
  issues jsonb,
  history_entry jsonb
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
#variable_conflict use_column
declare
  v_product catalog.products%rowtype;
  v_history_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.delete') then
    raise exception 'permission denied: catalog.product.delete';
  end if;

  select *
  into v_product
  from catalog.products p
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id
  for update;

  if not found then
    raise exception 'product not found';
  end if;

  if v_product.business_status <> 'soft_deleted'::catalog.product_business_status then
    raise exception 'product_restore_blocked: Product is not soft-deleted.';
  end if;

  if p_expected_version is not null and p_expected_version <> v_product.version then
    raise exception 'stale_product_version: expected=% current=%',
      p_expected_version,
      v_product.version;
  end if;

  if v_product.sku is not null and exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.id <> p_product_id
      and p.business_status <> 'soft_deleted'::catalog.product_business_status
      and p.sku = v_product.sku
  ) then
    raise exception 'duplicate sku "%"', v_product.sku;
  end if;

  if v_product.barcode is not null and exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.id <> p_product_id
      and p.business_status <> 'soft_deleted'::catalog.product_business_status
      and p.barcode = v_product.barcode
  ) then
    raise exception 'duplicate barcode "%"', v_product.barcode;
  end if;

  update catalog.products
  set deleted_at = null,
      business_status = 'inactive',
      updated_at = now(),
      updated_by = p_actor_id,
      version = catalog.products.version + 1
  where tenant_id = p_tenant_id
    and id = p_product_id;

  perform * from catalog._refresh_product_readiness(p_tenant_id, p_product_id);

  insert into catalog.product_change_history (
    tenant_id,
    product_id,
    action,
    payload,
    actor_id
  )
  values (
    p_tenant_id,
    p_product_id,
    'product_restored',
    jsonb_build_object(
      'value_before', 'soft_deleted',
      'value_after', 'inactive',
      'business_status_after', 'inactive',
      'reason', nullif(btrim(coalesce(p_reason, '')), '')
    ),
    p_actor_id
  )
  returning id into v_history_id;

  perform catalog.enqueue_outbox_message(
    p_tenant_id,
    'catalog.product.restored',
    jsonb_build_object(
      'tenant_id', p_tenant_id,
      'product_id', p_product_id,
      'business_status', 'inactive',
      'reason', nullif(btrim(coalesce(p_reason, '')), '')
    )
  );

  return query
  select *
  from catalog._product_soft_delete_result_row(
    p_tenant_id,
    p_product_id,
    p_reason,
    '[]'::jsonb,
    v_history_id
  );
end;
$$;
